class SporadicGraphTask:
    def __init__(self, graph_of_subtasks, period, deadline):
        self.G = graph_of_subtasks  # Graph structure
        self.T = period
        self.D = deadline
        self.subtasks = graph_of_subtasks.get_subtasks() # Set of subtasks

def is_idle_time(time, pending_subtasks):
    return not any(subtask.release_time <= time and subtask.is_pending() for subtask in pending_subtasks)

def find_busy_periods(schedule):
    busy_periods = []
    start_time = None
    for t in range(schedule.total_time):
        if not is_idle_time(t, schedule.all_subtasks):
            if start_time is None:
                start_time = t
        else:
            if start_time is not None:
                busy_periods.append((start_time, t))
                start_time = None
    if start_time is not None: # Handle busy period extending to end of schedule
        busy_periods.append((start_time, schedule.total_time))
    return busy_periods

def calculate_C_i_j_max(all_subtasks_in_system, pi_i_j_star):
    max_C = 0
    for subtask in all_subtasks_in_system:
        if subtask.pi > pi_i_j_star:
            max_C = max(max_C, subtask.C)
    return max_C

def get_pi_i_j_star(canonical_chain_P_i_j_star, target_subtask_tau_i_j):
    return target_subtask_tau_i_j.pi # Priority after canonicalization

def get_pi_i_j_paren(canonical_chain_P_i_j_star, target_subtask_tau_i_j):
    j_index = canonical_chain_P_i_j_star.index(target_subtask_tau_i_j)
    lowest_priority = 0 # Assuming 0 is highest priority, so lowest priority is max value
    for i in range(j_index + 1):
        lowest_priority = max(lowest_priority, canonical_chain_P_i_j_star[i].pi)
    return lowest_priority

def classify_segments(chain, pi_i_j_star, target_subtask_tau_i_j):
    segments = []
    current_segment = []
    current_type = None # 'H' or 'L'

    for subtask in chain:
        segment_priority_type = 'H' if subtask.pi <= pi_i_j_star else 'L'
        if not current_segment or segment_priority_type == current_type:
            current_segment.append(subtask)
            current_type = segment_priority_type
        else:
            segments.append({'type': current_type, 'subtasks': current_segment})
            current_segment = [subtask]
            current_type = segment_priority_type
    if current_segment: segments.append({'type': current_type, 'subtasks': current_segment})

    H_mp_segments = []
    H_sb_segments = []
    H_mb_segment = None

    for i, segment_info in enumerate(segments):
        if segment_info['type'] == 'H':
            if i == 0 or segments[i-1]['type'] == 'H':
                H_mp_segments.append(segment_info['subtasks'])
            else: # preceded by 'L'
                H_sb_segments.append(segment_info['subtasks'])

            # Check for H_mb (if target_subtask_tau_i_j is in the previous segment)
            if i > 0 and target_subtask_tau_i_j in segments[i-1]['subtasks']:
                H_mb_segment = segment_info['subtasks']

    return H_mp_segments, H_sb_segments, H_mb_segment

def calculate_segment_execution_time(segment_subtasks):
    total_C = 0
    for subtask in segment_subtasks:
        total_C += subtask.C
    return total_C

def create_interference_sets(all_chains, pi_i_j_star, target_subtask_tau_i_j):
    MP_set = []
    SB_set = []
    for chain in all_chains:
        H_mp_segments, H_sb_segments, H_mb_segment = classify_segments(chain, pi_i_j_star, target_subtask_tau_i_j)
        MP_set.extend(H_mp_segments)
        if H_mb_segment: MP_set.append(H_mb_segment)
        SB_set.extend(H_sb_segments)
    return MP_set, SB_set

