def calculate_WCRT(N_i, T_i, finish_times_F_i_j_k):
    max_response_time = 0
    for k in range(1, N_i + 1):
        response_time_k = finish_times_F_i_j_k[k] - (k - 1) * T_i
        max_response_time = max(max_response_time, response_time_k)
    return max_response_time

def is_schedulable_graph(graph_G):
    chain_P = transform_graph_to_chain(graph_G)
    return is_schedulable_chain(chain_P)

def check_execution_equivalence(original_subtask, canonical_subtask_or_segment):
    if isinstance(canonical_subtask_or_segment, list): # It's a merged segment
        return original_subtask.C == sum(s.C for s in canonical_subtask_or_segment)
    else:
        return original_subtask.C == canonical_subtask_or_segment.C

def calculate_preemptive_L_i_j(MP_set, SB_set, C_i_1):
    L_i_j_current = C_i_1 # Initial guess
    while True:
        interference_MP = 0
        for segment_h in MP_set:
            interference_MP += ceil(L_i_j_current / segment_h.T) * segment_h.E

        blocking_SB = 0
        if SB_set:
            blocking_SB = max(calculate_segment_execution_time(s) for s in SB_set)

        L_i_j_next = interference_MP + blocking_SB + C_i_1

        if L_i_j_next == L_i_j_current:
            return L_i_j_current
        L_i_j_current = L_i_j_next

def calculate_non_preemptive_L_i_j(MP_set, SB_set, all_subtasks_in_system, pi_i_j_star, C_i_1):
    # Calculate M_i_j
    blocking_SB = 0
    if SB_set:
        blocking_SB = max(calculate_segment_execution_time(s) for s in SB_set)

    blocking_other_low_priority = 0
    for subtask_m in all_subtasks_in_system:
        if subtask_m.parent_task_id != C_i_1.parent_task_id and subtask_m.pi > pi_i_j_star:
            blocking_other_low_priority = max(blocking_other_low_priority, subtask_m.C)

    C_i_j_max_val = calculate_C_i_j_max(all_subtasks_in_system, pi_i_j_star)

    M_i_j = max(blocking_SB, blocking_other_low_priority, C_i_j_max_val)

    L_i_j_current = C_i_1 # Initial guess
    while True:
        interference_MP = 0
        for segment_h in MP_set:
            interference_MP += ceil(L_i_j_current / segment_h.T) * segment_h.E

        L_i_j_next = interference_MP + M_i_j + C_i_1

        if L_i_j_next == L_i_j_current:
            return L_i_j_current
        L_i_j_current = L_i_j_next

def calculate_preemptive_W_i_1_k_t(t, k, C_i_1, MP_1_set, SB_set, E_i_1_val):
    M_i_1 = 0
    if SB_set:
        M_i_1 = max(calculate_segment_execution_time(s) for s in SB_set)

    interference_MP = 0
    for segment_h in MP_1_set:
        interference_MP += ceil(t / segment_h.T) * segment_h.E

    workload = C_i_1 + M_i_1 + interference_MP + k * E_i_1_val
    return workload

def calculate_preemptive_F_i_1_k(k, C_i_1, MP_1_set, SB_set, E_i_1_val):
    t_current = C_i_1 # Initial guess for t
    while True:
        workload = calculate_preemptive_W_i_1_k_t(t_current, k, C_i_1, MP_1_set, SB_set, E_i_1_val)
        if workload <= t_current:
            return t_current
        t_current = workload

def calculate_preemptive_F_i_j_k(k, C_i_j, F_i_j_minus_1_k, MP_j_set):
    t_current = F_i_j_minus_1_k + C_i_j # Initial guess for t
    while True:
        interference_MP = 0
        for segment_h in MP_j_set:
            # Only consider interference from F_i_j_minus_1_k onwards
            interference_MP += ceil(max(0, t_current - F_i_j_minus_1_k) / segment_h.T) * segment_h.E

        demand = C_i_j + interference_MP + F_i_j_minus_1_k

        if demand <= t_current:
            return t_current
        t_current = demand

def calculate_non_preemptive_W_i_1_k(k, C_i_1, MP_1_set, SB_set, all_subtasks_in_system, pi_i_1_star, E_i_1_val):
    # Calculate Y_i_1 (similar to M_i_j from Claim 4)
    blocking_SB = 0
    if SB_set:
        blocking_SB = max(calculate_segment_execution_time(s) for s in SB_set)
    blocking_other_low_priority = 0
    for subtask_m in all_subtasks_in_system:
        if subtask_m.parent_task_id != C_i_1.parent_task_id and subtask_m.pi > pi_i_1_star:
            blocking_other_low_priority = max(blocking_other_low_priority, subtask_m.C)
    C_i_j_max_val = calculate_C_i_j_max(all_subtasks_in_system, pi_i_1_star)
    Y_i_1 = max(blocking_SB, blocking_other_low_priority, C_i_j_max_val)

    W_i_1_k_current = C_i_1 # Initial guess
    while True:
        interference_MP = 0
        for segment_h in MP_1_set:
            interference_MP += ceil(W_i_1_k_current / segment_h.T) * segment_h.E

        W_i_1_k_next = C_i_1 + Y_i_1 + interference_MP + (k - 1) * E_i_1_val

        if W_i_1_k_next == W_i_1_k_current:
            return W_i_1_k_current
        W_i_1_k_current = W_i_1_k_next

def calculate_non_preemptive_W_i_j_k(k, C_i_j, F_i_j_minus_1_k, MP_j_set):
    W_i_j_k_current = F_i_j_minus_1_k + C_i_j # Initial guess
    while True:
        interference_MP = 0
        for segment_h in MP_j_set:
            interference_MP += ceil(max(0, W_i_j_k_current - F_i_j_minus_1_k) / segment_h.T) * segment_h.E

        demand = F_i_j_minus_1_k + C_i_j + interference_MP

        if demand <= W_i_j_k_current:
            return W_i_j_k_current
        W_i_j_k_current = demand

def calculate_hybrid_Y_i_1(SB_set, all_subtasks_in_system, pi_i_1_star, C_i_1_ref):
    blocking_SB = 0
    if SB_set:
        blocking_SB = max(calculate_segment_execution_time(s) for s in SB_set)

    blocking_other_non_preemptive_low_priority = 0
    for subtask_m in all_subtasks_in_system:
        if subtask_m.parent_task_id != C_i_1_ref.parent_task_id and subtask_m.pi > pi_i_1_star and subtask_m.is_non_preemptive:
            blocking_other_non_preemptive_low_priority = max(blocking_other_non_preemptive_low_priority, subtask_m.C)

    C_i_j_max_val = calculate_C_i_j_max(all_subtasks_in_system, pi_i_1_star)

    return max(blocking_SB, blocking_other_non_preemptive_low_priority, C_i_j_max_val)
